import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"🔍 搜索查询","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"features/search.md","filePath":"features/search.md"}'),i={name:"features/search.md"};function d(o,t,s,c,n,h){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="🔍-搜索查询" tabindex="-1">🔍 搜索查询 <a class="header-anchor" href="#🔍-搜索查询" aria-label="Permalink to &quot;🔍 搜索查询&quot;">​</a></h1><p>搜索页是 EmuTrain 最强大的功能模块，支持<strong>车次查询</strong>与<strong>动车组车号查询</strong>两种模式，可自由切换多个数据源。</p><hr><h2 id="车次查询" tabindex="-1">车次查询 <a class="header-anchor" href="#车次查询" aria-label="Permalink to &quot;车次查询&quot;">​</a></h2><p>输入任意车次号，即可查询该次列车的完整信息。</p><h3 id="支持的车次类型" tabindex="-1">支持的车次类型 <a class="header-anchor" href="#支持的车次类型" aria-label="Permalink to &quot;支持的车次类型&quot;">​</a></h3><ul><li><strong>高铁 / 动车</strong>：G、D、C 字头</li><li><strong>普速列车</strong>：K、T、Z 字头</li><li><strong>城际 / 旅游</strong>：IC、S 字头等</li></ul><h3 id="查询结果包含" tabindex="-1">查询结果包含 <a class="header-anchor" href="#查询结果包含" aria-label="Permalink to &quot;查询结果包含&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>停靠站点</td><td>全程所有经停车站列表</td></tr><tr><td>到发时刻</td><td>每站的到达与出发时间</td></tr><tr><td>担当车型</td><td>当日运行的动车组型号</td></tr><tr><td>车组号</td><td>具体担当车组的编号</td></tr><tr><td>重联信息</td><td>重联编组时显示两节车组</td></tr><tr><td>始发终到</td><td>全程首末站信息</td></tr></tbody></table><h3 id="数据源选择" tabindex="-1">数据源选择 <a class="header-anchor" href="#数据源选择" aria-label="Permalink to &quot;数据源选择&quot;">​</a></h3><p>在<strong>设置 → 数据源</strong>中切换车次查询的数据源：</p><details class="details custom-block"><summary>Rail.re（推荐）</summary><ul><li>API：<code>https://api.rail.re/train/{车次}</code></li><li>第三方 API，数据较丰富</li><li>支持重联显示、城际车次</li><li>部分特殊车次可能缺数据</li></ul></details><details class="details custom-block"><summary>RailGo</summary><ul><li>API：<code>https://emu.data.railgo.zenglingkun.cn/train/{车次}</code></li><li>第三方 API，数据较丰富</li><li>支持重联显示、城际车次</li><li>部分特殊车次可能缺数据</li></ul></details><details class="details custom-block"><summary>12306 官方</summary><ul><li>搜索接口：<code>https://search.12306.cn/search/v1/train/search?keyword={车次}&amp;date={日期}</code></li><li>车辆信息：<code>https://mobile.12306.cn/...</code></li><li>购票接口：<code>https://kyfw.12306.cn/otn/leftTicket/queryG</code></li><li>官方权威数据，最准确可靠</li><li>不显示重联编组、城际等特殊信息</li></ul></details><hr><h2 id="动车组查询-车号-交路查询" tabindex="-1">动车组查询（车号 / 交路查询） <a class="header-anchor" href="#动车组查询-车号-交路查询" aria-label="Permalink to &quot;动车组查询（车号 / 交路查询）&quot;">​</a></h2><p>输入动车组车组号，查询其当日担当交路及车组信息。</p><h3 id="输入格式示例" tabindex="-1">输入格式示例 <a class="header-anchor" href="#输入格式示例" aria-label="Permalink to &quot;输入格式示例&quot;">​</a></h3><ul><li><code>CRH380A-1001</code></li><li><code>CR400BF-4501</code></li><li><code>CR400AF-L-2001</code></li><li>也可只输入末四位数字进行模糊匹配</li></ul><h3 id="查询结果包含-1" tabindex="-1">查询结果包含 <a class="header-anchor" href="#查询结果包含-1" aria-label="Permalink to &quot;查询结果包含&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>车组号</td><td>完整车组编号</td></tr><tr><td>车型</td><td>动车组型号（如 CRH380A、CR400BF 等）</td></tr><tr><td>配属路局</td><td>所属铁路局集团</td></tr><tr><td>配属段</td><td>具体配属的动车段</td></tr><tr><td>制造厂家</td><td>生产厂商信息</td></tr><tr><td>当日交路</td><td>今日担当的具体车次</td></tr><tr><td>站点信息</td><td>交路中的停靠站点</td></tr><tr><td>是否重联</td><td>是否处于重联状态</td></tr></tbody></table><h3 id="数据源选择-1" tabindex="-1">数据源选择 <a class="header-anchor" href="#数据源选择-1" aria-label="Permalink to &quot;数据源选择&quot;">​</a></h3><details class="details custom-block"><summary>Rail.re</summary><ul><li>API：<code>https://api.rail.re/emu/{车组号}</code></li><li>综合动车组信息与交路</li></ul></details><details class="details custom-block"><summary>RailGo</summary><ul><li>API：<code>https://emu.data.railgo.zenglingkun.cn/emu/{车组号}</code></li><li>综合动车组信息与交路</li></ul></details><details class="details custom-block"><summary>MoeFactory</summary><ul><li>API：<code>https://rail.moefactory.com/api/emuSerialNumber/query</code></li><li>全面的车型信息数据库</li><li>另有车站大屏接口：<code>https://rail.moefactory.com/api/station/getBigScreenInfo</code></li><li>线路详情接口：<code>https://rail.moefactory.com/api/trainDetails/queryTrainRoutes</code></li></ul></details><hr><h2 id="车站查询" tabindex="-1">车站查询 <a class="header-anchor" href="#车站查询" aria-label="Permalink to &quot;车站查询&quot;">​</a></h2><p>通过输入起点站与终点站，还可查询两站之间今日运行的所有车次。</p><p>数据来源：</p><ul><li><strong>MoeFactory</strong>：<code>https://sharyou.moefactory.com/api/trainNumber/query</code>（推荐）</li><li><strong>携程</strong>：<code>https://m.ctrip.com/restapi/soa2/14674/json/GetTrainStopTimeInfo</code></li></ul><hr><h2 id="智能匹配" tabindex="-1">智能匹配 <a class="header-anchor" href="#智能匹配" aria-label="Permalink to &quot;智能匹配&quot;">​</a></h2><p>EmuTrain 的搜索引擎支持<strong>智能模糊匹配</strong>：</p><ul><li>输入车型前缀自动推荐（如输入 <code>CRH3</code> 匹配所有 CRH3 系列）</li><li>输入末四位数字匹配对应车组</li><li>多结果时按匹配分数从高到低排列</li></ul><hr><h2 id="从搜索直接添加行程" tabindex="-1">从搜索直接添加行程 <a class="header-anchor" href="#从搜索直接添加行程" aria-label="Permalink to &quot;从搜索直接添加行程&quot;">​</a></h2><p>在车次查询结果页面，可直接点击<strong>添加到旅途</strong>，将当前车次与区间一键加入旅行记录，无需重复输入。</p>',37)])])}const p=a(i,[["render",d]]);export{m as __pageData,p as default};
